{
  "criterios": [
    {
      "id": 1,
      "criterio": "Explico la ecuación global de la fotosíntesis y ubico cada fase en el cloroplasto (tilacoides y estroma).",
      "niveles": [
        {
          "nivel": "inicial",
          "puntos": 1,
          "descriptor": "Puedo nombrar la fotosíntesis y mencionar algunos reactivos o productos, pero aún confundo dónde ocurre cada fase dentro del cloroplasto."
        },
        {
          "nivel": "en desarrollo",
          "puntos": 2,
          "descriptor": "Puedo escribir la ecuación global con reactivos y productos, pero ubico solo una fase o dudo entre tilacoides y estroma."
        },
        {
          "nivel": "logrado",
          "puntos": 3,
          "descriptor": "Puedo escribir la ecuación global balanceada y ubicar la fase luminosa en los tilacoides y el ciclo de Calvin en el estroma."
        }
      ]
    },
    {
      "id": 2,
      "criterio": "Describo la fase luminosa: absorción de luz, fotólisis del agua, transporte de electrones y producción de ATP y NADPH.",
      "niveles": [
        {
          "nivel": "inicial",
          "puntos": 1,
          "descriptor": "Puedo decir que la clorofila absorbe luz, pero no distingo los pasos ni explico qué productos genera esta fase."
        },
        {
          "nivel": "en desarrollo",
          "puntos": 2,
          "descriptor": "Puedo describir la absorción de luz y mencionar ATP, NADPH y O₂ como productos, pero omito el papel de los fotosistemas o de la cadena de transporte."
        },
        {
          "nivel": "logrado",
          "puntos": 3,
          "descriptor": "Puedo explicar cómo los fotosistemas II y I, la fotólisis del agua y la cadena de electrones generan ATP, NADPH y O₂."
        }
      ]
    },
    {
      "id": 3,
      "criterio": "Explico las etapas del ciclo de Calvin: fijación de CO₂ por la rubisco, reducción y regeneración de RuBP.",
      "niveles": [
        {
          "nivel": "inicial",
          "puntos": 1,
          "descriptor": "Puedo indicar que el ciclo de Calvin usa CO₂ para formar azúcares, pero no reconozco sus etapas ni la función de la rubisco."
        },
        {
          "nivel": "en desarrollo",
          "puntos": 2,
          "descriptor": "Puedo nombrar la fijación de CO₂ por la rubisco y la formación de G3P, pero me cuesta explicar la reducción o la regeneración de RuBP."
        },
        {
          "nivel": "logrado",
          "puntos": 3,
          "descriptor": "Puedo explicar la fijación de CO₂ por la rubisco, la reducción a G3P con ATP y NADPH, y la regeneración de RuBP."
        }
      ]
    },
    {
      "id": 4,
      "criterio": "Relaciono ambas fases mostrando qué moléculas produce una y consume la otra, y de dónde proviene el O₂ liberado.",
      "niveles": [
        {
          "nivel": "inicial",
          "puntos": 1,
          "descriptor": "Puedo describir cada fase por separado, pero no veo cómo se conectan ni sé de qué molécula proviene el oxígeno liberado."
        },
        {
          "nivel": "en desarrollo",
          "puntos": 2,
          "descriptor": "Puedo decir que la fase luminosa aporta ATP y NADPH al ciclo de Calvin, pero olvido el retorno de ADP y NADP⁺ o el origen del O₂."
        },
        {
          "nivel": "logrado",
          "puntos": 3,
          "descriptor": "Puedo trazar el flujo entre fases: ATP y NADPH pasan al ciclo de Calvin, ADP y NADP⁺ regresan, y el O₂ proviene del agua."
        }
      ]
    },
    {
      "id": 5,
      "criterio": "Analizo cómo la intensidad de luz, la concentración de CO₂ y la temperatura modifican la tasa de fotosíntesis.",
      "niveles": [
        {
          "nivel": "inicial",
          "puntos": 1,
          "descriptor": "Puedo mencionar que la luz o la temperatura influyen en la fotosíntesis, pero no explico por qué ni cómo cambia su tasa."
        },
        {
          "nivel": "en desarrollo",
          "puntos": 2,
          "descriptor": "Puedo describir el efecto de la luz, el CO₂ o la temperatura, pero no identifico con claridad qué fase o enzima se ve limitada."
        },
        {
          "nivel": "logrado",
          "puntos": 3,
          "descriptor": "Puedo interpretar una gráfica o situación y explicar qué factor limita la tasa, relacionándolo con la fase luminosa, la rubisco o la desnaturalización enzimática."
        }
      ]
    }
  ],
  "reflexiones": {
    "5-8": "Tu puntaje indica que estás en las primeras etapas de comprensión. Vuelve a los conceptos base: dibuja un cloroplasto y ubica en él dónde ocurre cada fase. Luego arma un cuadro con lo que entra y sale de cada una. Pregúntate: ¿qué parte del proceso todavía no puedo explicar con mis palabras? Consulta a tu docente o a un compañero sobre ese punto.",
    "9-12": "Vas por buen camino: entiendes las ideas principales, pero aún hay conexiones por reforzar. Identifica los criterios donde marcaste «en desarrollo» y explícalos en voz alta, sin apuntes. Practica siguiendo un átomo de carbono desde el CO₂ hasta el G3P, y el flujo de electrones desde el agua hasta el NADPH. Pregúntate: ¿puedo justificar cada paso con su porqué?",
    "13-15": "Muestras un dominio sólido de la fotosíntesis y de la relación entre sus dos fases. Para consolidarlo, explica el proceso a un compañero o resuelve un problema nuevo, por ejemplo qué ocurre si se bloquea el transporte de electrones. Pregúntate: ¿qué aspecto podría profundizar, como la fotorrespiración o las plantas C4 y CAM, y cómo aplicaría lo aprendido?"
  }
}
